export interface LineItem {
  sku: string;
  quantity: number;
  unitCents: number;
}

export interface Order {
  customerId: string;
  status: "open" | "shipped" | "cancelled";
  lines: LineItem[];
  coupon: string | null;
  tier: "standard" | "gold" | "blocked";
  weightKg: number;
}

export function ordersFor(orders: Order[], customerId: string, onlyOpen: boolean): Order[] {
  return orders.filter(
    (order) => order.customerId === customerId && (!onlyOpen || order.status === "open"),
  );
}

const GOLD_DISCOUNT_PERCENT = 10;
const WELCOME_DISCOUNT_PERCENT = 5;

export function discountPercent(order: Order): number {
  let percent = 0;
  if (order.lines.length > 0) {
    if (order.tier !== "blocked") {
      if (order.tier === "gold") {
        percent = GOLD_DISCOUNT_PERCENT;
      } else {
        if (order.coupon === "WELCOME") {
          percent = WELCOME_DISCOUNT_PERCENT;
        }
      }
    }
  }
  return percent;
}

export function shippingCents(order: Order): number {
  return 450 + Math.ceil(order.weightKg) * 120;
}

export function subtotalCents(order: Order): number {
  return order.lines.reduce((sum, line) => sum + line.quantity * line.unitCents, 0);
}

export function totalCents(order: Order): number {
  const subtotal = subtotalCents(order);
  const discount = Math.round((subtotal * discountPercent(order)) / 100);
  return subtotal - discount + shippingCents(order);
}

export function averageTotalCents(orders: Order[]): number {
  const total = orders.reduce((sum, order) => sum + totalCents(order), 0);
  return total / orders.length;
}

